# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">TEDVİN VE TASNİF SONRASI TAMAMLAYICI HADİS ÇALIŞMALARI (HDS.10.2.3)</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. MÜSTEDREK VE MÜSTAHREC ESERLER</text>\n  <text x="32" y="88" font-size="10.8" font-weight="bold" fill="#1e3a8a">• Müstedrek (الْمُسْتَدْرَكُ):</text>\n  <text x="40" y="106" font-size="10.2" fill="#1e3a8a">Bir müellifin şartlarına uyduğu hâlde eserine almadığı</text>\n  <text x="40" y="122" font-size="10.2" fill="#1e3a8a">hadisleri toplayan eser. Örnek: Hâkim en-Nîsâbûrî,</text>\n  <text x="40" y="138" font-size="10.2" font-weight="bold" fill="#1d4ed8">el-Müstedrek ale\'s-Sahîhayn (Buhârî ve Müslim\'e ek).</text>\n  <text x="32" y="158" font-size="10.8" font-weight="bold" fill="#1e3a8a">• Müstahrec (الْمُسْتَخْرَجُ):</text>\n  <text x="40" y="176" font-size="10.2" fill="#1e3a8a">Temel bir hadis kaynağındaki hadisleri, müellifin senedinden</text>\n  <text x="40" y="192" font-size="10.2" fill="#1e3a8a">farklı (kendi) isnad zinciriyle yeniden rivayet eden eser.</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. CEM\' VE ZEVÂİD EDEBİYATI</text>\n  <text x="372" y="88" font-size="10.8" font-weight="bold" fill="#14532d">• Cem\' (الْجَمْعُ) Eserleri:</text>\n  <text x="380" y="106" font-size="10.2" fill="#14532d">Birden fazla temel hadis kaynağındaki hadisleri senedleri</text>\n  <text x="380" y="122" font-size="10.2" fill="#14532d">kısaltıp tekrarları çıkararak tek eserde birleştiren çalışma.</text>\n  <text x="380" y="138" font-size="10.2" font-weight="bold" fill="#15803d">Örnek: İbnü\'l-Esîr, Câmiu\'l-Usûl; Begavî, Mesâbîhu\'s-Sünne.</text>\n  <text x="372" y="158" font-size="10.8" font-weight="bold" fill="#14532d">• Zevâid (الزَّوَائِدُ) Eserleri:</text>\n  <text x="380" y="176" font-size="10.2" fill="#14532d">Bir hadis kaynağının (ör. Müsned) Kütüb-i Sitte\'den fazla</text>\n  <text x="380" y="192" font-size="10.2" fill="#14532d">olarak içerdiği hadisleri derleyen eser (Heysemî, Mecmau\'z-Zevâid).</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Hicri IV. asırdan itibaren hadis çalışmaları; temel kaynakları tamamlama, birleştirme ve açıklama yönünde gelişmiştir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">HADİS ŞERH EDEBİYATI, ETRAF VE HALK HADİSLERİ TÜRÜ ESERLER</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">MEŞHUR HADİS ŞERHLERİ (الشُّرُوحُ)</text>\n  <text x="32" y="88" font-size="10.6" fill="#78350f">• Hattâbî: Meâlimü\'s-Sünen (İlk Sünen-i Ebû Dâvûd şerhi)</text>\n  <text x="32" y="110" font-size="10.6" fill="#78350f">• İbn Hacer el-Askalânî: Fethu\'l-Bârî (Sahîh-i Buhârî şerhi)</text>\n  <text x="32" y="132" font-size="10.6" fill="#78350f">• Bedreddin el-Aynî: Umdetü\'l-Kârî (Sahîh-i Buhârî şerhi)</text>\n  <text x="32" y="154" font-size="10.6" fill="#78350f">• İmam Nevevî: el-Minhâc (Sahîh-i Müslim şerhi)</text>\n  <text x="32" y="176" font-size="10.6" fill="#78350f">• Mübârekfûrî: Tuhfetü\'l-Ahvezî (Sünen-i Tirmizî şerhi)</text>\n  <text x="32" y="196" font-size="10.2" font-weight="bold" fill="#92400e">→ Kelime tahlili, sened tenkidi ve fıkhi hükümleri açıklar.</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">DİĞER DERLEME VE İNDEKS TÜRLERİ</text>\n  <text x="372" y="88" font-size="10.6" fill="#581c87">• Etrâf Eserleri: Hadisin baş kısmını vererek geçtiği</text>\n  <text x="372" y="106" font-size="10.2" fill="#581c87">  kaynakları ve senedleri gösteren fihrist/indeks eserleri.</text>\n  <text x="372" y="126" font-size="10.6" fill="#581c87">• Erbaûn (Kırk Hadis): Belli bir konuda 40 hadis derleme</text>\n  <text x="372" y="144" font-size="10.2" fill="#581c87">  geleneği (Örnek: İmam Nevevî\'nin Kırk Hadis\'i).</text>\n  <text x="372" y="164" font-size="10.6" fill="#581c87">• Riyâzü\'s-Sâlihîn (Nevevî): Ahlak ve fazilet derlemesi.</text>\n  <text x="372" y="184" font-size="10.6" fill="#581c87">• Keşfü\'l-Hafâ (Aclûnî): Halk arasındaki meşhur sözler.</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Cumhuriyet döneminde Babanzâde Ahmed Naim ve Kâmil Miras, Tecrîd-i Sarîh Terceme ve Şerhi\'ni hazırlamıştır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">HADİS TARİHİ DÖNEMLERİ ÖZET AKIŞ ŞEMASI (2. ÜNİTE DEĞERLENDİRMESİ)</text>\n  <rect x="18" y="45" width="155" height="165" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="95" y="65" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">1. TESBİT DÖNEMİ</text>\n  <text x="95" y="82" text-anchor="middle" font-size="10" fill="#1e3a8a">(Asr-ı Saâdet &amp; Sahâbe)</text>\n  <text x="26" y="104" font-size="9.8" fill="#1e3a8a">• Hıfz (ezber) ve müzakere</text>\n  <text x="26" y="122" font-size="9.8" fill="#1e3a8a">• Özel sahîfeler (es-Sahîfetü\'s-</text>\n  <text x="26" y="138" font-size="9.8" fill="#1e3a8a">  Sâdıka, Hemmâm b. Münebbih)</text>\n  <text x="26" y="156" font-size="9.8" fill="#1e3a8a">• Rihle ve isnadın başlaması</text>\n  <rect x="185" y="45" width="155" height="165" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="262" y="65" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">2. TEDVİN DÖNEMİ</text>\n  <text x="262" y="82" text-anchor="middle" font-size="10" fill="#14532d">(Hicri I. Asır Sonu - II. Asır)</text>\n  <text x="193" y="104" font-size="9.8" fill="#14532d">• Halife Ömer b. Abdülaziz\'in</text>\n  <text x="193" y="120" font-size="9.8" fill="#14532d">  resmî tedvin emri</text>\n  <text x="193" y="138" font-size="9.8" fill="#14532d">• İbn Şihâb ez-Zührî\'nin</text>\n  <text x="193" y="154" font-size="9.8" fill="#14532d">  öncülüğünde toplama</text>\n  <text x="193" y="172" font-size="9.8" fill="#14532d">• Karışık derleme süreci</text>\n  <rect x="352" y="45" width="155" height="165" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="429" y="65" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">3. TASNİF DÖNEMİ</text>\n  <text x="429" y="82" text-anchor="middle" font-size="10" fill="#78350f">(Hicri II. Asır Ortası - III. Asır)</text>\n  <text x="360" y="104" font-size="9.8" fill="#78350f">• Konularına göre: Musannef,</text>\n  <text x="360" y="120" font-size="9.8" fill="#78350f">  Muvatta, Câmi\', Sünen</text>\n  <text x="360" y="138" font-size="9.8" fill="#78350f">• Ravilerine göre: Müsned,</text>\n  <text x="360" y="154" font-size="9.8" fill="#78350f">  Mu\'cem</text>\n  <text x="360" y="172" font-size="9.8" font-weight="bold" fill="#92400e">• Kütüb-i Sitte &amp; Tis\'a (Altın Çağ)</text>\n  <rect x="519" y="45" width="163" height="165" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="600" y="65" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">4. TASNİF SONRASI</text>\n  <text x="600" y="82" text-anchor="middle" font-size="10" fill="#581c87">(Hicri IV. Asır ve Sonrası)</text>\n  <text x="527" y="104" font-size="9.8" fill="#581c87">• Müstedrek &amp; Müstahrec</text>\n  <text x="527" y="122" font-size="9.8" fill="#581c87">• Cem\' &amp; Zevâid edebiyatı</text>\n  <text x="527" y="140" font-size="9.8" fill="#581c87">• Hadis Şerhleri (Fethu\'l-Bârî,</text>\n  <text x="527" y="156" font-size="9.8" fill="#581c87">  Umdetü\'l-Kârî, el-Minhâc)</text>\n  <text x="527" y="174" font-size="9.8" fill="#581c87">• Kırk Hadis &amp; Etrâf eserleri</text>\n  <rect x="18" y="222" width="664" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="239" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Hadis tarihi; ezber ve sahîfelerden resmî tedvine, sistematik tasnife ve nihayet şerh-derleme dönemine uzanır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
